export interface Section { id: string; title: string; html: string }
export interface Page { slug: string; title: string; group: string; description: string; icon: IconName; keywords?: string; sections: Section[] }
export const escapeHTML = (text: string): string => text.replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]!);
export const link = (slug: string, label: string) => `<a href="#/${slug}">${label}</a>`;
export const note = (text: string, title = 'Good to know') => `<aside class="note">${icon('leaf')}<div><strong>${title}</strong><p>${text}</p></div></aside>`;
export function code(source: string, filename = 'example.js'): string {
  const tokens = source.split(/(\/\/[^\n]*|'[^'\n]*'|"[^"\n]*"|\b(?:import|from|const|let|new|return|export|function|interface|type|if|true|false|null|undefined)\b|\b\d+(?:\.\d+)?\b)/g);
  const highlighted = tokens.map(token => {
    const kind = token.startsWith('//') ? 'comment' : /^["']/.test(token) ? 'string' : /^\d/.test(token) ? 'number' : /^(import|from|const|let|new|return|export|function|interface|type|if|true|false|null|undefined)$/.test(token) ? 'keyword' : '';
    return kind ? `<span class="token-${kind}">${escapeHTML(token)}</span>` : escapeHTML(token);
  }).join('');
  return `<div class="code-block"><div class="code-head"><span>${icon('code')}${filename}</span><button data-copy aria-label="Copy ${filename}">${icon('copy')}<span>Copy</span></button></div><pre tabindex="0"><code>${highlighted}</code></pre></div>`;
}
export const table = (headers: string[], rows: string[][]) => `<div class="table-scroll" tabindex="0" role="region" aria-label="${escapeHTML(headers.join(', '))} table"><table><thead><tr>${headers.map(h => `<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row => `<tr>${row.map(c => `<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
export const live = (type: ChartType, compact = false) => `<div class="live-example${compact ? ' compact' : ''}" data-example="${type}"><div class="example-toolbar"><span><i class="status-dot"></i>LIVE EXAMPLE <b>${chartTypes[type].name}</b></span><div><button data-detail aria-pressed="false" aria-label="Essential chart detail" title="Essential chart detail">${icon('sliders-horizontal')}</button><button data-refresh aria-label="Refresh ${type} sample data" title="Refresh data">${icon('arrows-clockwise')}</button><button data-table aria-label="Show ${type} data table" aria-pressed="false" title="Show data table">${icon('table')}</button></div></div><div class="example-chart"></div><div class="example-caption">${icon('cursor')}<span>Hover or focus a mark to read its value.</span></div></div>`;
const card = (slug: string, title: string, description: string, name: IconName) => `<a class="link-card" href="#/${slug}"><span class="card-icon">${icon(name)}</span><strong>${title}${icon('arrow-up-right')}</strong><p>${description}</p></a>`;
export { chartIcons } from '../chart-icons';
const section = (id: string, title: string, html: string): Section => ({ id, title, html });
const specimen = (type: ChartType): string => {
  const detail=studyDetails[type];
  return `<div class="specimen-note" data-specimen-chart="${type}"><div class="native-specimen" data-mini-chart="${type}" aria-hidden="true" inert></div><div><span class="overline">THE NATURAL FORM · NATIVE SVG</span><p class="specimen-observation">${detail.observation}</p><p>${detail.craft}</p><a href="../?study=${type}#nature-studies">Explore this chart and its practical example ${icon('arrow-right')}</a></div></div>`;
};

const quickCode = `import { NaturePlot } from 'natureplot';

const chart = new NaturePlot('#chart', {
  type: 'forest',
  title: 'A week of deep work',
  unit: 'h',
  data: [
    { label: 'Mon', value: 4 },
    { label: 'Tue', value: 6 },
    { label: 'Wed', value: 5 },
    { label: 'Thu', value: 8 },
    { label: 'Fri', value: 6.5 },
  ],
});`;

